statement.tex:
\begin{enumerate}
  \item 2直線 $y=2x,\ y=-3x$ のなす角を求めよ．
  \item 点 $(1,2)$ を通り，直線 $y=2x$ と $45^\circ$ の角をなす直線の方程式をすべて求めよ．
  \item 直線 $y=2x$ を原点のまわりに $45^\circ$ 回転した直線の方程式を求めよ．
\end{enumerate}

2直線 $l:3x-4y+2=0$，$m:4x+3y-1=0$ がある．
\begin{enumerate}
  \item 点 $(1,1)$ と $l$ の距離を求めよ．
  \item $l$ と $m$ のなす角の二等分線の方程式を求めよ．
  \item 半径1で $l,m$ の両方に接する円のうち，中心が第1象限にあるものの中心をすべて求めよ．
\end{enumerate}

3直線 $l:x+2y=4$，$m:2x-y=3$，$n:ax+y=a+1$ がある．
\begin{enumerate}
  \item $n$ は $a$ の値によらず定点を通ることを示し，その点を求めよ．
  \item 3直線が三角形を作らないような $a$ の値をすべて求めよ．
  \item $a=1$ のとき，3直線が作る三角形の面積を求めよ．
\end{enumerate}

直線 $l:y=2x$ と2点 A$(4,1)$，B$(3,1)$ がある．
\begin{enumerate}
  \item $l$ に関して A と対称な点 A$'$ の座標を求めよ．
  \item 点 P が $l$ 上を動くとき，$AP+PB$ の最小値と，そのときの P の座標を求めよ．
\end{enumerate}

放物線 $y=x^2$ と直線 $y=mx+2$ の2つの交点を P，Q とする．
\begin{enumerate}
  \item 線分 PQ の長さを $m$ で表し，その最小値を求めよ．
  \item $PQ=3\sqrt2$ となる $m$ を求めよ．
  \item 線分 PQ の中点の軌跡を求めよ．
\end{enumerate}

放物線 $y=x^2$ に，点 P$(a,b)$ から2本の接線が引けるとする．
\begin{enumerate}
  \item 2本の接線が直交するとき，P はどのような図形上にあるか．また，このとき2つの接点を結ぶ直線は定点を通ることを示せ．
  \item 2本の接線のなす角が $45^\circ$ となる点 P の軌跡を求めよ．
\end{enumerate}

円 $C:x^2+y^2=25$ と直線 $l:kx-y-2k+1=0$ がある．
\begin{enumerate}
  \item $l$ は $k$ によらず定点を通ることを示し，その点を求めよ．
  \item $l$ が $C$ から切り取る弦の長さの最小値を求めよ．（$k$ は実数全体を動く）
  \item 弦の長さが 8 となる $k$ は存在するか．
\end{enumerate}

2円 $C_1:x^2+y^2=5$，$C_2:x^2+y^2-4x-2y+3=0$ がある．
\begin{enumerate}
  \item 2円の交点を通る直線の方程式と，2つの交点の座標を求めよ．
  \item 2円の交点を通り，中心が直線 $y=x+1$ 上にある円の方程式を求めよ．
  \item 2円の交点を通る円のうち，半径が最小のものの方程式を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 点 P$(3,1)$ から円 $x^2+y^2=5$ に引いた2本の接線の方程式と接点の座標を求めよ．
  \item 中心が $x$ 軸上にあり，2直線 $y=x$，$y=-x+4$ の両方に接する円のうち，中心が $0<x<4$ にあるものを求めよ．
\end{enumerate}

solutions.tex:
中心 $(p,q)$，半径 $r\ (>0)$ として $|p|=|q|=r$，$|3p+4q-12|=5r$．$p,q$ の符号で場合分けする．
\begin{itemize}
  \item $p=q=r$：$|7r-12|=5r$ より $7r-12=\pm5r$，$r=6,\ 1$．
  \item $p=r,\ q=-r$：$|-r-12|=r+12=5r$ より $r=3$．
  \item $p=-r,\ q=r$：$|r-12|=5r$ より $r-12=\pm5r$，$r>0$ から $r=2$．
  \item $p=q=-r$：$|-7r-12|=7r+12=5r$ は $r>0$ で解なし．
\end{itemize}
よって
\begin{itemize}
  \item 内接円：中心 $(1,1)$，半径 $1$．
  \item 傍接円：中心 $(6,6)$，半径 $6$；中心 $(3,-3)$，半径 $3$；中心 $(-2,2)$，半径 $2$．
\end{itemize}
の \textbf{4個}．

statement.tex:
連立不等式 $(x-y)(x+y-4)\leqq0$，$x^2+y^2\leqq8$ の表す領域を $D$ とする．
\begin{enumerate}
  \item $D$ を図示し，面積を求めよ．
  \item 点 $(x,y)$ が $D$ を動くとき，$x+2y$ の最大値を求めよ．
\end{enumerate}

原点 O と異なる点 P に対し，半直線 OP 上の点 Q を $OP\cdot OQ=k$（$k>0$ は定数）となるように定める．
\begin{enumerate}
  \item $k=4$ とする．P が円 $(x-1)^2+y^2=1$（原点を除く）上を動くとき，Q の軌跡を求めよ．
  \item $k=3$ とする．P が円 $x^2+(y-1)^2=4$ 上を動くとき，Q の軌跡を求めよ．
\end{enumerate}

連立不等式 $x\geqq0,\ y\geqq0,\ x+2y\leqq8,\ 3x+y\leqq9$ の表す領域を $D$ とする．
\begin{enumerate}
  \item 点 $(x,y)$ が $D$ を動くとき，$2x+y$ の最大値を求めよ．
  \item 実数 $a$ に対し，$ax+y$ の最大値を $a$ で表せ．
\end{enumerate}

実数 $x,y$ が $x^2+y^2-6x-8y+21=0$ を満たすとき，
\begin{enumerate}
  \item $x^2+y^2$ の最大値と最小値を求めよ．
  \item $\dfrac yx$ の最大値と最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 曲線 $y=x^3+ax^2+bx$ が点 $(1,3)$ に関して対称となるような定数 $a,b$ を求めよ．
  \item 曲線 $y=x^3-3x^2+4x$ は，ある点に関して対称であることを示し，その点を求めよ．
\end{enumerate}

点 A$(2,1)$ から円 $x^2+y^2=1$ に2本の接線を引き，接点を P，Q とする．
\begin{enumerate}
  \item 直線 PQ の方程式と，線分 PQ の中点 M の座標を求めよ．
  \item $\triangle OPQ$ と $\triangle APQ$ の面積を求めよ．
\end{enumerate}

$a>0,\ b>0$ とし，P$(a,0)$，Q$(0,b)$ を2頂点とする正三角形 PQR を，R が原点と反対側にあるようにつくる．
\begin{enumerate}
  \item R の座標を $a,b$ で表せ．
  \item $PQ=2$ のとき，OR の最大値と，そのときの $a,b$ を求めよ．
\end{enumerate}

座標平面上に4点 O$(0,0)$，A$(3,0)$，B$(3,1)$，C$(0,1)$ をとる．実数 $a$ に対し4点 P$(a+1,a)$，Q$(a,a+1)$，R$(a-1,a)$，S$(a,a-1)$ をとる．
\begin{enumerate}
  \item 長方形 OABC と正方形 PQRS が共有点をもつような $a$ の範囲を求めよ．
  \item $\frac12\leqq a\leqq1$ のとき，共通部分の面積を $a$ で表せ．
  \item 共通部分の面積が最大となる $a$ の値と，そのときの面積を求めよ．
\end{enumerate}

原点 O を中心とする半径2の円 $C$ と，点 $(4,0)$ を通る傾き $m$ の直線 $l$ が異なる2点 A，B で交わる．
\begin{enumerate}
  \item $m$ の値の範囲を求めよ．
  \item 三角形 OAB の面積が $\sqrt3$ となる $m$ の値をすべて求めよ．
  \item 三角形 OAB の面積の最大値と，そのときの $m^2$ の値を求めよ．
\end{enumerate}

直線 $l:(1+2k)x+(2-k)y-11-2k=0$ は定数 $k$ の値によらず定点 A を通る．
\begin{enumerate}
  \item 定点 A の座標を求めよ．
  \item 原点 O と2点 A，B を頂点とする三角形 OAB が正三角形になるとき，その外接円の中心の座標を求めよ．
  \item 直線 $l$ と円 $x^2+y^2=20$ の2つの交点を通る円のうちに，2点 P$(-4,0)$，Q$(2,0)$ を通るものがある．このときの $k$ の値と円の方程式を求めよ．
\end{enumerate}

点 A$(0,a)$ を中心とする円 $x^2+(y-a)^2=b^2$ が，放物線 $y=x^2$ と異なる2点 P，Q で接している（$a>\frac12$）．
\begin{enumerate}
  \item $a$ と $b$ の関係式を求めよ．
  \item $\angle$PAQ$=90^\circ$ のとき，$a,b$ の値を求めよ．
  \item (2) のとき，円と放物線で囲まれた部分（円の下側）の面積を求めよ．
\end{enumerate}

$k$ を実数とし，放物線 $y=x^2$ と直線 $y=kx-k^2+2$ を考える．
\begin{enumerate}
  \item 2つのグラフが異なる2点で交わるための $k$ の範囲を求めよ．
  \item 2つの交点を A，B とするとき，線分 AB の中点 M の座標を $k$ で表せ．
  \item $k$ を変化させるとき，M の軌跡を求めよ．
\end{enumerate}

楕円 $E:\dfrac{x^2}4+y^2=1$ と，直線 $y=2$ 上の点 P$(t,2)$ を考える．P から $E$ に2本の接線を引き，接点を M，N とする．直線 OP と弦 MN の交点を Q とする．
\begin{enumerate}
  \item 直線 MN の方程式を求めよ．
  \item Q の座標を $t$ で表せ．
  \item P が直線 $y=2$ 上を動くとき，Q の軌跡を求めよ．
\end{enumerate}

不等式 $\log_2x+\log_2(4-x)\geqq\log_2y\geqq2\log_2x-1$ を満たす点 $(x,y)$ 全体の領域を $D$ とする．
\begin{enumerate}
  \item $D$ を図示せよ．
  \item $a<4$ を満たす定数 $a$ に対し，$D$ 上での $y-ax$ の最大値 $M(a)$ を求めよ．
\end{enumerate}

A$(0,0)$，B$(2,0)$，C$(2,1)$，D$(0,1)$ を頂点とする長方形の辺 BC，CD，DA，AB 上にそれぞれ点 P，Q，R，S を，$\angle$BPS$=\angle$QPC，$\angle$PQC$=\angle$RQD，$\angle$QRD$=\angle$SRA，$\angle$RSA$=\angle$PSB となるようにとる．ただし P，Q，R，S は長方形の頂点とは一致しないものとする．
\begin{enumerate}
  \item 線分 BP の長さ $t$ のとりうる値の範囲を求め，Q，R，S の座標を $t$ で表せ．
  \item 四角形 PQRS の面積の最大値を求めよ．
  \item 直線 AP と直線 RS の交点を T とする．四角形 PQRT の面積 $f(t)$ を求め，$f(t)$ を最大にする $t$ は $u=t+1$ が $u^3-u^2-1=0$ をみたす値であることを示せ．
\end{enumerate}

$m$ を実数とし，円 $C:(x-m)^2+y^2=m^2+4$ と直線 $l:y=mx+2$ を考える．
\begin{enumerate}
  \item $C$ と $l$ が異なる2点で交わる $m$ の範囲を求めよ．
  \item 交点を P，Q とし，PQ の中点 N の座標を $m$ で表せ．
  \item $m$ が (1) の範囲を動くとき，N の軌跡を求めよ．
\end{enumerate}

原点中心，半径2の円を $C$，点 $(1,1)$ を通る傾き $a$ の直線を $l$ とする．
\begin{enumerate}
  \item $C$ と $l$ は異なる2点で交わることを示せ．
  \item 2つの交点 P，Q における $C$ の接線の交点を R とする．$a$ が実数全体を動くとき，R の軌跡を求めよ．
\end{enumerate}

次は［問題＃］とそれに対する［A 君の途中までの解答］である．
\begin{quote}
［問題＃］$s,t$ が $0\leqq s\leqq1$，$0\leqq t\leqq1$ の範囲を動くとき，$x=s+t$，$y=st$ で定まる点 $(x,y)$ が動く範囲を図示せよ．

［A 君の解答］$s=x-t$ を代入して $y=(x-t)t$．したがって，$0\leqq t\leqq1$ のとき放物線 $y=(x-t)t$ が通過する範囲を求めればよい．
\end{quote}
A 君の解答の問題点を理由とともに指摘し，［問題＃］の正しい解答を与えよ．

実数 $x,y$ が $x^2+xy+y^2\leqq3$ をみたしながら変化する．
\begin{enumerate}
  \item $s=x+y$，$t=xy$ とするとき，点 $(s,t)$ の動く範囲を図示せよ．
  \item $m\geqq0$ を定数とするとき，$xy+m(x+y)$ の最大値と最小値を $m$ で表せ．
\end{enumerate}

$a,b,c$ は0以上の実数とする．3点 A$(a,0)$，B$(0,b)$，C$(1,c)$ が $\angle$ABC$=60^\circ$，$\angle$BAC$=30^\circ$ をみたす．
\begin{enumerate}
  \item $c$ を求め，$b$ を $a$ で表せ．
  \item AB の長さの最大値と最小値を求めよ．
\end{enumerate}

点 $(a,3)$ を中心とし原点 O を通る円 $C$ が，放物線 $y=x^2$ と異なる4点で交わるとする．
\begin{enumerate}
  \item $a$ のみたす条件を求めよ．
  \item $a$ が (1) の条件をみたしながら変化するとき，$C$ が通過する範囲を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 実数 $x,y$ が $x^2+y^2-4y=1$ をみたすとき，$2x+y$ の最大値と最小値を求めよ．
  \item 実数 $x,y$（$(x,y)\neq(0,0)$）に対し $z=\dfrac{x^2-xy+2y^2}{x^2+y^2}$ のとりうる値の範囲を求めよ．
\end{enumerate}

座標平面上に点 O$(0,0)$，A$(1,2)$ と，$a>0$ に対して直線 $l:\ y=-ax+3a+3$ がある．
\begin{enumerate}
  \item 直線 $l$ に関して A と対称な点 A$'$ の座標を求めよ．
  \item 点 P が $l$ 上を動くときの OP$+$PA の最小値を $f(a)$ とする．$f(a)^2$ を $a$ で表せ．
  \item $f(a)$ を最大にする $a$ の値と，その最大値を求めよ．
\end{enumerate}

放物線 $y=x^2$ 上の2点 P$(s,s^2)$，Q$(t,t^2)$ が $t-s=1$，$s>0$，PQ$=\sqrt{10}$ を満たしている．
\begin{enumerate}
  \item P，Q の座標を求めよ．
  \item 放物線 $y=6-(x-1)^2$ のうち領域 $y\geqq x^2$ に含まれる部分を $C$ とする．点 R が $C$ 上を動くとき，$\triangle$PQR の面積の最大値と最小値，およびそのときの R の座標を求めよ．
\end{enumerate}

2つの円 $x^2+y^2=4$，$(x-6)^2+y^2=16$ がある．
\begin{enumerate}
  \item 直線 $y=mx+n$ が2つの円に接するとき，$m,n$ を求めよ．
  \item 2つの円の共通接線の方程式をすべて求めよ．
\end{enumerate}

3つの直線 $3x+4y=36$，$4x-3y=23$，$12x+5y=-43$ によって囲まれる三角形について，
\begin{enumerate}
  \item 3つの頂点の座標を求めよ．
  \item 内接円の方程式を求めよ．
\end{enumerate}

点 P が円 $x^2+y^2=4$ 上を，点 Q が円 $x^2+y^2-8x+6y+21=0$ 上を動く．
\begin{enumerate}
  \item 線分 PQ の長さの最大値と最小値を求めよ．
  \item 線分 PQ の中点 M が動く範囲の面積を求めよ．
\end{enumerate}

円 $C:\ x^2+(y-b)^2=r^2$（$b>0,\ r>0$）が放物線 $y=\dfrac12x^2$ と原点以外の2点で接している．
\begin{enumerate}
  \item $b$ を $r$ で表し，接点の座標と $r$ のとりうる値の範囲を求めよ．
  \item $C$ が点 $(0,3)$ を通るときの $r$ の値をすべて求めよ．
\end{enumerate}

$k$ を実数とし，放物線 $C:\ y=x^2+2x$ と直線 $L:\ y=kx-k^2$ を考える．
\begin{enumerate}
  \item $C$ と $L$ が異なる2点 P，Q で交わる $k$ の範囲を求めよ．
  \item 線分 PQ の中点 M の軌跡を求めよ．
\end{enumerate}

放物線 $C:\ y=\dfrac14x^2$ と，$x$ 軸の下側の点 P$(s,t)$ がある．P から $C$ に引いた2本の接線を $l_1,l_2$，接点を Q$_1$，Q$_2$ とし，Q$_1$ は第1象限，Q$_2$ は第2象限にあるとする．
\begin{enumerate}
  \item $l_1,l_2$ の傾き $m_1,m_2$ について，$m_1+m_2$ と $m_1m_2$ を $s,t$ で表せ．
  \item $l_1\perp l_2$ となる点 P の軌跡を求めよ．
  \item $\angle$Q$_1$PQ$_2=45^\circ$ となる点 P の軌跡を求めよ．
\end{enumerate}

実数 $a$ に対し，放物線 $C:\ y=x^2-2ax+3a^2-2a$ を考える．
\begin{enumerate}
  \item $a$ がすべての実数を動くとき，$C$ が通過する領域を求めよ．
  \item $a$ が $0\leqq a\leqq1$ の範囲を動くとき，$C$ が通過する領域を求めよ．
\end{enumerate}

連立不等式 $x+y\geqq2$，$x^2+y^2\leqq4x$ の表す領域を $D$ とする．
\begin{enumerate}
  \item 直線 $x+y=2$ と円 $x^2+y^2=4x$ の交点を求めよ．
  \item 点 $(x,y)$ が $D$ を動くとき，$3y-x$ の最大値と最小値を求めよ．
\end{enumerate}

連立不等式 $y\leqq2x+4$，$y\geqq x^2+1$ の表す領域を $D$ とする．点 $(x,y)$ が $D$ を動くとき，
\begin{enumerate}
  \item $x+y$ の最大値と最小値を求めよ．
  \item $y+x^2-4x$ の最小値と，そのときの点 $(x,y)$ を求めよ．
  \item $\dfrac{y}{x-4}$ の最大値と，そのときの点 $(x,y)$ を求めよ．
\end{enumerate}

$a,b$ は定数とし，円 $(x-a)^2+(y-b)^2=4$ を $C$ とする．2点 O$(0,0)$，A$(2,0)$ のうち，片方が円 $C$ の内部に含まれ，もう片方が円 $C$ の外部に含まれるとする．
\begin{enumerate}
  \item $a,b$ の満たす条件を求めよ．
  \item (1) の条件を満たす点 $(a,b)$ の存在範囲の面積を求めよ．
\end{enumerate}

関数 $f(x)=|x-1|-3$ について，
\begin{enumerate}
  \item 関数 $y=|f(x)|$ を区間ごとに絶対値を含まない式で表せ．
  \item 関数 $y=|f(x)|$ のグラフが，直線 $y=kx+1$ と相異なる4点で交わるような実数 $k$ の範囲を求めよ．
\end{enumerate}

$a,b,c$ は0以上の実数とする．3点 A$(a,0)$，B$(0,b)$，C$(1,c)$ は $\angle$ABC$=45^\circ$，$\angle$BAC$=45^\circ$ を満たす．
\begin{enumerate}
  \item $c$ の値を求め，$a,b$ の関係式を求めよ．
  \item AB の長さの最大値と最小値を求めよ．
\end{enumerate}

$p<q$ を満たす実数とする．実数 $a,b$ に対して，2次方程式 $x^2+ax+b=0$ のすべての解が $p$ 以上 $q$ 以下の実数であるような点 $(a,b)$ 全体の領域を $D$ とする．
\begin{enumerate}
  \item $D$ を表す連立不等式を求め，$D$ の面積を $p,q$ の式で表せ．
  \item $p=-1,\ q=1$ のとき，$D$ のうち $b\geqq0$ を満たす部分の面積を求めよ．
\end{enumerate}

円 $x^2+(y-1)^2=1$ を $C$，円 $(x-4)^2+(y-4)^2=16$ を $C_0$ とする．$C$，$C_0$，$x$ 軸に接する円で2円の間にあるものを $C_1$ とする．$C$，$C_1$，$x$ 軸に接し $C_0$ と異なる円を $C_2$ とし，これを繰り返して $C$，$C_n$，$x$ 軸に接し $C_{n-1}$ と異なる円を $C_{n+1}$ とする．$C_n$ の半径を $a_n$ とする（$a_0=4$）．
\begin{enumerate}
  \item $C$ と $C_0$ が外接していることを確かめ，$a_1$ を求めよ．
  \item $b_n=\dfrac1{\sqrt{a_n}}$ とするとき，数列 $\{b_n\}$ の満たす漸化式を求めよ．
  \item 数列 $\{a_n\}$ の一般項を求めよ．
\end{enumerate}

O を原点とする座標平面上に放物線 $C_1:\ y=x^2$ と円 $C_2:\ x^2+(y-a)^2=4$（$a\geqq0$）がある．$C_2$ の点 $(0,a+2)$ における接線と $C_1$ が2点 A，B で交わり，$\triangle$OAB が $C_2$ に外接しているとする．
\begin{enumerate}
  \item $a$ を求めよ．
  \item $C_1$ 上の点 P$(\alpha,\alpha^2)$（$\alpha^2\neq4$）から $C_2$ に2本の接線を引き，それらが再び $C_1$ と交わる点を Q$(\beta,\beta^2)$，R$(\gamma,\gamma^2)$ とする．$\beta+\gamma$ および $\beta\gamma$ を $\alpha$ で表せ．
  \item 直線 QR は $C_2$ に接することを示せ．
\end{enumerate}

平面上で点Pから直線 $l$ に引いた垂線と $l$ との交点を，点Pから直線 $l$ に下ろした垂線の足という．
\begin{enumerate}
  \item 点 $\mathrm P(p,q)$ から直線 $ax+by+c=0$ に下ろした垂線の足の座標を求めよ．
  \item 3点 A$(3,1)$，B$(-1,3)$，C$(-3,-1)$ を考える．直線AB，BC，CAを $l_1,l_2,l_3$ とし，点 $\mathrm P(p,q)$ から $l_1,l_2,l_3$ へ下ろした垂線の足を $\mathrm H_1,\mathrm H_2,\mathrm H_3$ とする．3点 $\mathrm H_1,\mathrm H_2,\mathrm H_3$ が一直線上にあるような点Pの軌跡を求めよ（3点のうち2点以上が一致する場合も一直線上にあるとみなす）．
\end{enumerate}

不等式 $|x+y|+|2x-y|\leqq3$ の表す領域を $D$ とする．
\begin{enumerate}
  \item 領域 $D$ を図示せよ．
  \item 領域 $D$ における $x+3y$ の最大値および最小値を求めよ．
  \item 領域 $D$ における $|x|-|y|$ の最大値および最小値を求めよ．
\end{enumerate}

$xy$ 平面上で，原点以外の互いに異なる3点 $\mathrm P_1(a_1,b_1)$，$\mathrm P_2(a_2,b_2)$，$\mathrm P_3(a_3,b_3)$ をとる．さらに，3直線 $l_i:a_ix+b_iy=1$（$i=1,2,3$）をとる．
\begin{enumerate}
  \item 2直線 $l_1,l_2$ が点 $\mathrm A(p,q)$ で交わるとき，2点 $\mathrm P_1,\mathrm P_2$ を通る直線の方程式が $px+qy=1$ であることを示せ．
  \item 3点 $\mathrm P_1,\mathrm P_2,\mathrm P_3$ が直線 $x+2y=1$ 上にあるとき，3直線 $l_1,l_2,l_3$ はある1点を通ることを示し，その点を求めよ．
  \item 3点 $\mathrm P_1,\mathrm P_2,\mathrm P_3$ が原点を通る直線上にあるとき，3直線 $l_1,l_2,l_3$ は互いに平行であることを示せ．
\end{enumerate}

2つの円 $x^2+y^2-2x-4y=0$，$(x-3)^2+(y+2)^2=r^2$ について，次の設問に答えよ．ただし，$r$ は正の定数とする．
\begin{enumerate}
  \item 2つの円が共有点を持たないための $r$ の必要十分条件を求めよ．
  \item $r=3$ のとき，2つの円の交点を通る直線の方程式を求めよ．
  \item $r=5$ のとき，2つの円の交点，及び点 $(0,1)$ を通る円の方程式を求めよ．
\end{enumerate}

$xy$ 平面上に，曲線 $C_1:y=\dfrac{x^2}4-1$ と，原点を中心とする半径1の円 $C_2$ がある．
\begin{enumerate}
  \item $t$ を0でない実数とする．曲線 $C_1$ 上の点 $\left(t,\frac{t^2}4-1\right)$ から円 $C_2$ へ引いた2本の接線が，それぞれ点 $\mathrm P_1,\mathrm P_2$ で $C_2$ と接する．$\mathrm P_1,\mathrm P_2$ を通る直線 $l$ の方程式を求めよ．
  \item (1) で求めた直線 $l$ は，$t$ の値にかかわらず，ある円に接することを示し，その円の方程式を求めよ．
\end{enumerate}

放物線 $C:y=\dfrac{x^2}4$ と平面上の点 $\mathrm P(a,b)$ について，以下の問いに答えなさい．
\begin{enumerate}
  \item 点 $\left(t,\frac{t^2}4\right)$ における $C$ の接線に，点Pから下ろした垂線の足Hの座標を $a,b,t$ を用いて表しなさい．
  \item (1) において，$t$ がすべての実数を動くときの点Hの軌跡が $x$ 軸に平行な直線になったとする．このとき，点Pの座標と点Hの軌跡の方程式を求めなさい．
\end{enumerate}

$xy$ 平面の双曲線 $y=\dfrac1x$ 上の相異なる3点を，A，B，Cとし，それらの $x$ 座標を，それぞれ $a,b,c$ とする．
\begin{enumerate}
  \item $\triangle$ABC の外心を $\mathrm P(x,y)$ とする．$x,y$ を $a,b,c$ を用いて表せ．
  \item $a,b,c$ が $a+b=0$，$c=2$ を満たすとき，$\mathrm P(x,y)$ の軌跡を求め，図示せよ．
\end{enumerate}

$a$ を実数とし，座標平面上に2点 $\mathrm A(a,a)$，$\mathrm B(2,0)$ があるとき，次の問いに答えよ．
\begin{enumerate}
  \item 2点A，Bから等距離にある点の軌跡を表す方程式を $a$ を用いて表せ．
  \item 線分ABの垂直二等分線を $l$ とする．$a$ が実数全体を動くとき，直線 $l$ が通る点 $(x,y)$ の全体を図示せよ．
  \item $a$ が $0\leqq a\leqq4$ の範囲を動くとき，直線 $l$ が通る点 $(x,y)$ の全体を表す条件を求めよ．
\end{enumerate}

座標平面上で3点 A$(-1,0)$，B$(1,0)$，C$(x,y)$ を頂点とする三角形を考える．$y>0$ とする．
\begin{enumerate}
  \item $\triangle$ABC が鋭角三角形で，3辺の中で AB の長さが最大（他の辺と等しい場合を含む）となる点Cの範囲を図示せよ．
  \item (1) の範囲の面積を求めよ．
\end{enumerate}

直線 $l:x\sin\theta+y\cos\theta=1$（$0<\theta<\frac\pi2$）に接し，中心が第1象限にある円を考える．$t=\sin\theta+\cos\theta$ とする．
\begin{enumerate}
  \item $x\sin\theta+y\cos\theta<1$ の領域で2つの円が互いに接しており，そのうち1つの円は直線 $l$ と $x$ 軸に，もう一方の円は直線 $l$ と $y$ 軸に接している．これらの円の半径はいずれも $r_1$ である．$r_1=\dfrac1{t^2+t}$ を示せ．
  \item $r_1$ のとり得る値の範囲を求めよ．
  \item 直線 $l$，$x$ 軸，$y$ 軸のすべてに接し，$x\sin\theta+y\cos\theta<1$ の領域にある円の半径を $\rho$ とする．$\dfrac{r_1}\rho$ を $t$ で表し，そのとり得る値の範囲を求めよ．
\end{enumerate}

実数 $a,b$ に対して，$xy$ 平面上の点 $\mathrm P(a+b,\ ab)$ を考える．次の問いに答えよ．
\begin{enumerate}
  \item $a,b$ がすべての実数を動くとき，Pの存在範囲を $xy$ 平面上に図示せよ．
  \item $a,b$ が $|a|+|b|\leqq2$ をみたしながら動くとき，Pの存在範囲を $xy$ 平面上に図示せよ．
  \item 点 $(x,y)$ が (2) で求めた範囲を動くとき，$y-x$ の最大値と最小値を求めよ．
\end{enumerate}

$xy$ 平面上で，$x,y$ 座標がともに整数である点を格子点という．
\begin{enumerate}
  \item 各格子点を中心として半径 $r$ の円が描かれている．傾き $\frac34$ の任意の直線がこれらの円のどれかと共有点をもつような $r$ の値の範囲を求めよ．
  \item $m+n$ が偶数である格子点 $(m,n)$ だけを中心として半径 $r$ の円を描く．傾き $\frac13$ の任意の直線がこれらの円のどれかと共有点をもつような $r$ の値の範囲を求めよ．
  \item (1) の円で，傾きが $\sqrt2$ の場合を考える．どんな正の数 $r$ に対しても，傾き $\sqrt2$ の任意の直線がどれかの円と共有点をもつことを示せ．
\end{enumerate}

$k$ を実数として，2直線 $\ell_1:\ y=k(x+1)$，$\ell_2:\ ky=-(x-3)$ を考える．
\begin{enumerate}
  \item $k$ がすべての実数値をとって変化するとき，$\ell_1$，$\ell_2$ の交点Pの軌跡を求めよ．
  \item $k$ が $k\geqq1$ の範囲を変化するとき，Pの軌跡を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 点 $(x,y)$ を点 $(x+2y,\ 2x+3y)$ に移す変換を $f$ とする．直線 $x+y=1$ の $f$ による像と原像を求めよ．
  \item 点 $(x,y)$ を点 $(x-2y+1,\ -2x+4y)$ に移す変換を $g$ とする．
  \begin{enumerate}
    \item 平面全体の $g$ による像を求めよ．
    \item 直線 $y=\frac12x+k$（$k$ は定数）と直線 $y=x$ の $g$ による像をそれぞれ求めよ．
    \item 点 $(3,-4)$ と点 $(0,0)$ の $g$ による原像をそれぞれ求めよ．
  \end{enumerate}
\end{enumerate}

点 $(x,y)$ を点 $(x+1,\ x^2+y)$ に移す変換を $f$ とする．
\begin{enumerate}
  \item 放物線 $y=-x^2+2x$ の $f$ による像を求めよ．
  \item 領域 $y\geqq-x^2+2x$ の $f$ による像を求めよ．
  \item $f$ によって $x$ 軸上に移る点全体（$x$ 軸の原像）を求めよ．
\end{enumerate}

点 $(x,y)$ を点 $(x^2,y^2)$ に移す変換を $f$ とする．
\begin{enumerate}
  \item 直線 $x+y=1$ の $f$ による像を求めよ．また，直線 $x-y=1$ の像がこれと一致することを示せ．
  \item 領域 $x+y\geqq1$ の $f$ による像を求めよ．
  \item 領域 $x+y\leqq1$ の $f$ による像を求めよ．
\end{enumerate}

放物線 $y=x^2$ 上の相異なる2点 A，B における接線の交点を C とする．
\begin{enumerate}
  \item C が直線 $y=-1$ 上にあるように A，B が動くとき，$\triangle$ABC の重心 G の軌跡を求めよ．
  \item C が領域 $y\geqq0$ にあるように A，B が動くとき，G の存在範囲を求めよ．
\end{enumerate}

放物線 $y=x^2$ 上の $x>0$ の部分に点Pを，$x<0$ の部分に点Qをとり，点Pの点Qに関する対称点をRとする．
\begin{enumerate}
  \item 点Rの存在範囲を図示せよ．
  \item (1) の範囲のうち $-1\leqq x<0$ の部分の面積を求めよ．
\end{enumerate}

点 $(2,0)$ で $x$ 軸に接する円 $O_1$ と，点 $(-2,0)$ で $x$ 軸に接する円 $O_2$ が互いに外接している．ただし，両円の中心はともに $y>0$ の部分にある．
\begin{enumerate}
  \item 2円の半径を $r_1,r_2$ とするとき，$r_1r_2$ の値を求めよ．
  \item 2円が外接しながら半径を変えるとき，接点Pの描く図形を求めよ．
  \item $r_1\geqq r_2$ の範囲で動かすとき，Pの描く図形を求めよ．
\end{enumerate}

曲線 $C:y=x^2-2x$，直線 $\ell:y=x+a$，直線 $g:y=-x+b$ がある．
(i) $C$ と $\ell$ が異なる2点で交わる，(ii) $C$ が $\ell$ と $g$ から等しい長さの線分を切り取る，という2条件をみたしながら $a,b$ が変化する．
\begin{enumerate}
  \item $\ell$ と $g$ の交点の軌跡を求めよ．
  \item 傾きを $\pm m$（$m>0$）に変えても，2条件のもとで交点がつねに直線 $x=1$ 上にあることを示せ．
\end{enumerate}

放物線 $y=x^2$ 上の点 $\mathrm P(t,t^2)$ と原点Oを直径の両端とする円を $C(t)$ とする（$C(0)$ は原点）．
\begin{enumerate}
  \item $t$ が実数全体を動くとき，$C(t)$ の通過する領域を求めよ．
  \item $t>0$ の範囲を動くときの通過領域を求めよ．
\end{enumerate}

座標平面上で，3頂点がすべて格子点（$x,y$ 座標がともに整数の点）である三角形を格子三角形という．
\begin{enumerate}
  \item 格子三角形の面積は $\frac12$ 以上で，$\frac12$ の整数倍であることを示せ．
  \item 内部に格子点を含む格子三角形の面積は $\frac32$ 以上であることを示せ．
  \item 内部に格子点を含み，面積がちょうど $\frac32$ の格子三角形の例をあげよ．
\end{enumerate}

$a$ を実数とする．2曲線 $C_1:y=x^2-a$，$C_2:x=y^2-a$ がある．
\begin{enumerate}
  \item $C_1$ と $C_2$ の異なる共有点の個数を $a$ の値によって分類せよ．
  \item 共有点が4個のとき，それらは同一円周上にあることを示し，その円の中心と半径を求めよ．
\end{enumerate}

O$(0,0)$，A$(2,0)$，B$(2,1)$，C$(0,1)$ を頂点とする長方形OABCの頂点Oを，辺OA，OC（両端を含む）と交わる直線を折り目として折り返すとき，Oと重なる点をPとする．
\begin{enumerate}
  \item P$(X,Y)$ の存在範囲を求めて図示せよ．
  \item その範囲の面積を求めよ．$\tan\alpha=\frac12$（$0<\alpha<\frac\pi2$）をみたす $\alpha$ を用いてよい．
\end{enumerate}

\begin{enumerate}
  \item 点 $(3,4)$ と直線 $ax-y=2a-1$ の距離の最大値と，そのときの $a$ を求めよ．また，距離が $\sqrt5$ となる $a$ を求めよ．
  \item 点 A$(1,2)$ を通る直線が $x$ 軸，$y$ 軸の正の部分とそれぞれ P，Q で交わる．OP$+$OQ の最小値と，そのときの P を求めよ．
  \item (2) で，線分PQの長さの最小値を求めよ．
\end{enumerate}

2直線 $l_1:mx-y-m+1=0$，$l_2:x+my+m-3=0$ の交点をPとする．
\begin{enumerate}
  \item $m$ がすべての実数値をとって変わるとき，Pの軌跡を求めよ．
  \item $m$ が $m\geqq0$ の範囲を動くとき，Pの軌跡を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 点P$(0,c)$ と放物線 $y=x^2$ 上の点Qの距離の最小値を求めよ．
  \item $b$ を実数，$r>0$ とする．円 $x^2+(y-b)^2=r^2$ が領域 $y\geqq x^2$ に含まれるための条件を求めよ．
  \item 中心が $y$ 軸上にあり，領域 $x^2\leqq y\leqq2$ に含まれる円の半径の最大値を求めよ．
\end{enumerate}

$k$ を実数として，直線 $l:(2x+y-5)+k(x-y+2)=0$ を考える．
\begin{enumerate}
  \item $l$ は $k$ によらずある定点を通る．その座標を求めよ．
  \item 2点 P$(-2,1)$，Q$(4,2)$ を両端とする線分PQと $l$ が共有点をもつような $k$ の範囲を求めよ．また，線分PQ上の点で $l$ との共有点となり得ない点を求めよ．
\end{enumerate}

中心が $y$ 軸上の点 $(0,b)$ にある半径 $r$ の円が放物線 $y=x^2$ とちょうど2点で交わり，その2つの交点でいずれも円と放物線の接線が直交する（円の接線と放物線の接線が垂直）という．
\begin{enumerate}
  \item 交点を $(\pm t,t^2)$（$t>0$）とするとき，$b$ と $r$ を $t$ で表せ．
  \item $b$ と $r$ の関係式を求め，点 $(b,r)$ の存在範囲を図示せよ．
  \item このとき，円と放物線の交点がほかにないことを確かめよ．
\end{enumerate}

単位円 $C_0:x^2+y^2=1$ と点P$(t,0)$（$0<t<1$）がある．点Pを通る円 $C$ が次の2条件をみたす．
(i) $C_0$ と共有点をもち，その共有点で2円の接線が直交する．(ii) 点Pにおける $C$ の接線の傾きは2である．
\begin{enumerate}
  \item $C$ の中心Qの座標を $t$ で表せ．
  \item 点Pが $0<t<1$ を動くとき，点Qの軌跡を求めよ．
\end{enumerate}

$t$ がすべての実数をとるとき，3点 A$(t,t^2)$，B$(t,t-1)$，C$(t+\sqrt2,\ t^2-2t+2)$ について答えよ．
\begin{enumerate}
  \item 各 $t$ に対し，A，B，C は三角形をなすことを示せ．
  \item $\triangle$ABC が直角三角形になる $t$ をすべて求めよ．
  \item $\triangle$ABC が鋭角三角形になる $t$ の範囲を求めよ．
\end{enumerate}

平面上に3点 A$(2,1)$，B$(11,13)$，C$(-14,13)$ をとる．
\begin{enumerate}
  \item 3辺の長さを求め，$\angle$A が直角であることを示せ．
  \item $\triangle$ABC の内心の座標と内接円の半径を求めよ．
\end{enumerate}

原点以外の互いに異なる3点 P$_k(a_k,b_k)$（$k=1,2,3$）に対して，直線 $\ell_k:a_kx-b_ky=2$ を考える．
\begin{enumerate}
  \item $\ell_1,\ell_2$ が点 $(p,q)$ で交わるとき，直線 P$_1$P$_2$ の方程式は $px-qy=2$ であることを示せ．
  \item $\ell_1,\ell_2,\ell_3$ が1点で交わるとき，P$_1$，P$_2$，P$_3$ は同一直線上にあることを示せ．
  \item P$_1(1,0)$，P$_2(3,2)$，P$_3(5,4)$ のとき，3直線 $\ell_k$ の交点を求めよ．
\end{enumerate}

$k$ は正の定数で，$a,b$ は $a>0$，$b>0$，$a+b=k$ をみたしながら動く．2点 A$(a,0)$，B$(0,b)$ を通る直線を $\ell$ とする．
\begin{enumerate}
  \item 点 P$(a,b)$ と $\ell$ の距離の最大値を求めよ．
  \item 点 Q$(k,k)$ と $\ell$ の距離のとり得る値の範囲を求めよ．
\end{enumerate}

原点を中心とする半径3の円を $C_1$，点 $(1,0)$ を中心とする半径1の円を $C_2$ とする．点 $(a,b)$（$b>0$）を中心とする半径 $t$ の円 $C_3$ が $C_1$ に内接し，$C_2$ に外接する．
\begin{enumerate}
  \item $a,b$ を $t$ で表し，$t$ のとり得る値の範囲を求めよ．
  \item $b$ の最大値を求めよ．
\end{enumerate}

$xy$ 平面上に3点 O$(0,0)$，A$(1,0)$，B$(0,2)$ がある．
\begin{enumerate}
  \item OP$:$AP$=1:\sqrt2$ をみたす点 P の軌跡を求めよ．
  \item $0<b<1$ とする．OP$:$BP$=1:b$ をみたす点 P の軌跡を求めよ．
  \item OP$:$AP$:$BP$=1:\sqrt2:b$ をみたす点 P が存在するような $b$（$0<b<1$）の範囲を求めよ．
\end{enumerate}

$D_1:x^2+y^2-6x-2y+9\leqq0$，$D_2:x^2+y^2-8x-4y+18\leqq0$ とし，直線 $\ell:ax-y-a=0$ を考える．次の条件をみたす $a$ の範囲をそれぞれ求めよ．
\begin{enumerate}
  \item $D_1\cup D_2$ が $\ell$ と共有点をもつ．
  \item $D_1\cap D_2$ が $\ell$ と共有点をもつ．
  \item $D_1$ が $\ell$ と共有点をもち，かつ $D_2$ が $\ell$ と共有点をもつ．
\end{enumerate}

連立不等式 $x^2+y^2\leqq1$，$y\geqq x^2-1$ の表す領域を $D$ とする．
\begin{enumerate}
  \item $D$ の境界のうち放物線 $y=x^2-1$ の部分は $-1\leqq x\leqq1$ 全体であることを示せ．
  \item $D$ 内の点 $(x,y)$ に対して $\dfrac{y+4}{x-2}$ の最大値と，それを与える点を求めよ．
  \item 同じく最小値を求めよ．
\end{enumerate}

円 $C:x^2+(y+1)^2=4$ と，中心 $(a,0)$，半径1の円 $D$ が異なる2点で交わるとする．
\begin{enumerate}
  \item $a$ のとり得る値の範囲を求めよ．
  \item 2つの交点を通る直線の方程式を求めよ．
  \item $a$ が (1) の範囲を動くとき，(2) の直線が通過する領域を求めよ．
\end{enumerate}

実数 $x,y$ に対し $s=x+y$，$t=xy$ とおく．
\begin{enumerate}
  \item $x,y$ が実数全体を動くとき，点 $(s,t)$ の存在範囲を求めよ．
  \item $x,y$ が $x^2+y^2+x^2y^2=3$ をみたしながら動くとき，点 $(s,t)$ の描く図形を求めよ．
  \item (2) のとき，$(1+x)(1+y)$ のとり得る値の範囲を求めよ．
\end{enumerate}

$xy$ 平面上に3点 A$(a,b)$，B$(a+2,b)$，C$(a+1,b+1)$ がある．不等式 $y\geqq x^2$ の表す領域を $D$，$y\leqq x^2$ の表す領域を $E$ とする．
\begin{enumerate}
  \item 点 C が $D$ に含まれ，点 A と点 B が $E$ に含まれるような $a,b$ の条件を求めよ．
  \item (1) の条件をみたす点 $(a,b)$ の領域 $F$ の面積を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 任意の角 $\theta$ に対して $-1\leqq x\cos\theta+y\sin\theta\leqq y+1$ が成り立つ点 $(x,y)$ の全体からなる領域を図示し，その面積を求めよ．
  \item 任意の角 $\alpha,\beta$ に対して $-2\leqq x^2\cos\alpha+y\sin\beta\leqq2$ が成り立つ点 $(x,y)$ の全体からなる領域を図示し，その面積を求めよ．
\end{enumerate}

原点を中心とする半径2の円を $C$ とし，$x$ 軸上に点P$(a,0)$（$a>2$）をとる．Pから $C$ へ引いた2本の接線の接点を結ぶ直線が $x$ 軸と交わる点をQとする．
\begin{enumerate}
  \item Qの $x$ 座標を求めよ．
  \item 点Rが $C$ 上にあるとき，$\dfrac{\mathrm{PR}}{\mathrm{QR}}$ はRによらず一定であることを示し，その値を求めよ．
  \item $C$ 上の点Rが $\angle$PRQ$=90^\circ$ をみたすとき，Rの $x$ 座標と線分PRの長さを求めよ．
\end{enumerate}

A$(1,0)$，B$(-1,0)$ とする．A，Bと異なる点P$(x,y)$ は $\angle$APB が $60^\circ$ または $120^\circ$ となるように動く．
\begin{enumerate}
  \item $x^2-1=t$ とおくとき，$t$ と $y$ のみたす関係式を求めよ．
  \item 点Pの軌跡を図示せよ．
  \item 点Q$\left(4,\frac{\sqrt3}3\right)$ に対し，線分PQの長さの最小値を求めよ．
\end{enumerate}

実数 $t$ に対して，直線 $l_t:\ y=2tx-t^2$ を考える．$t$ が $|t|\geqq1$ をみたして動くとする．
\begin{enumerate}
  \item 点 $(0,-1)$，$\left(\frac12,0\right)$，$\left(\frac12,\frac14\right)$ のそれぞれについて，その点を通る $l_t$（$|t|\geqq1$）が存在するかどうかを判定せよ．
  \item $l_t$ の通過する領域を求め，図示せよ．
\end{enumerate}

$0\leqq t\leqq1$ をみたす実数 $t$ に対して，放物線 $C_t:\ y=x^2-2tx+2t^2$ を考える．
\begin{enumerate}
  \item 直線 $x=k$ 上で $C_t$ が通過する部分を，$k$ の値によって場合分けして求めよ．
  \item $C_t$ が通過する領域を図示せよ．
  \item (2) の領域のうち $0\leqq x\leqq2$ の部分の面積を求めよ．
\end{enumerate}

O を原点とする．放物線 $y=x^2$ 上に原点以外の点 A$(t,t^2)$（$t\neq0$）をとる．
\begin{enumerate}
  \item 線分 OA の垂直二等分線の方程式を求めよ．
  \item A が放物線上の原点以外の部分全体を動くとき，線分OAの垂直二等分線が通過する範囲を求めよ．
\end{enumerate}

実数 $x,y$ が $(x-4)^2+(y-3)^2\leqq4$ をみたしながら動くとき，次の最小値・最大値を求めよ．
\begin{enumerate}
  \item $x^2+y^2-2x$
  \item $(x+1)^2+(y-1)^2+(x-3)^2+(y-1)^2$
\end{enumerate}

2つの放物線 $C:y=x^2+px+q$，$D:y=-x^2+2x+3$ が異なる2点で交わり，その2点を通る直線が $y=4x+1$ であるという．
\begin{enumerate}
  \item $p,q$ の値を求めよ．
  \item 2つの交点を結ぶ線分の中点の座標を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 楕円 $x^2+4y^2=4$ と放物線 $y=x^2-2$ は4点で交わることを示し，この4点が同一円周上にあることを示して，その円の中心と半径を求めよ．
  \item 2つの放物線 $y=2x^2-x$，$x=y^2-3y$ の4つの交点を通る円を求めよ（$x^2$ と $y^2$ の係数が異なる点に注意せよ）．
\end{enumerate}

2円 $C_1:x^2+y^2-10=0$，$C_2:x^2+y^2-4x-2y+2=0$ がある．
\begin{enumerate}
  \item $C_1$，$C_2$ は2点で交わることを示し，2交点を通る直線を求めよ．
  \item 2交点を通る円のうち，中心が直線 $x+3y=2$ 上にあるものを求めよ．
  \item 2交点を通る円のうち，半径が最小のものを求めよ．また，それが束 $C_1+kC_2=0$ のどの $k$ に対応するか答えよ．
\end{enumerate}

$a\neq0$ とし，放物線 $C:y=ax^2+x-b$ と直線 $y=2x$ が異なる2点で交わるとする．
\begin{enumerate}
  \item 2交点を結ぶ線分を直径とする円 $K$ の方程式を $a,b$ で表せ．
  \item $C$ と $K$ が4点で交わるとき，4点はすべて放物線 $x=py^2+qy+r$ 上にあることを示し，$p,q,r$ を $a,b$ で表せ．
  \item $a=b=1$ のとき，$C$ と $K$ の交点をすべて求め，(2) を確かめよ．
\end{enumerate}

原点Oと異なる点Pに対し，直線OP上の点Qを，OP$\cdot$OQ$=4$ かつ QがOに関してPと同じ側にあるようにとる．
\begin{enumerate}
  \item 点Pが直線 $x+y=2$ 上を動くとき，Qの軌跡を求めよ．
  \item 点Pが2点 $(2,0)$，$(0,2)$ を結ぶ線分上を動くとき，Qの軌跡を求め，図示せよ．
\end{enumerate}

点 $(x,y)$ が $x\geqq0$，$y\geqq0$，$3x+5y\leqq30$，$4x+3y\leqq24$ の表す領域 $D$ を動く．
\begin{enumerate}
  \item $x+y$ の最大値と，そのときの $(x,y)$ を求めよ．
  \item $x,y$ が整数のとき，$x+y$ の最大値と，そのときの $(x,y)$ を求めよ．
\end{enumerate}

連立不等式 $x+y\geqq4$，$x-y\leqq2$，$x+2y\leqq10$ の表す領域を $D$ とする．
\begin{enumerate}
  \item $D$ の頂点を求めよ．
  \item $m$ を定数とする．$(x,y)$ が $D$ を動くとき，$mx+y$ の最大値，最小値をそれぞれ $m$ で表せ．
\end{enumerate}

実数 $x,y,z$ が $x\leqq y\leqq z\leqq2$ かつ $x+2y+3z=6$ をみたす．
\begin{enumerate}
  \item $xy$ 平面上に点 $(x,y)$ の存在範囲を図示せよ．
  \item $2x+y-z$ のとり得る値の範囲を求めよ．
\end{enumerate}

$xy$ 平面上に2点 A$(1,0)$，B$(4,0)$ と直線 $l:y=mx$（$m\neq0$）がある．
\begin{enumerate}
  \item 直線 $l$ に関する点Bの対称点 $\mathrm B'$ を求めよ．
  \item $l$ 上に点Pを，$\mathrm{AP}+\mathrm{PB}$ が最小となるようにとる．Pの座標を $m$ で表せ．
  \item $m$ が0以外の実数全体を動くとき，Pの描く図形を求めよ．
\end{enumerate}

双曲線 $xy=1$ 上に相異なる3点 A$\left(a,\frac1a\right)$，B$\left(b,\frac1b\right)$，C$\left(c,\frac1c\right)$ がある．
\begin{enumerate}
  \item $\triangle$ABC の垂心 H は双曲線上にあり，H$=\left(-\dfrac1{abc},\ -abc\right)$ であることを示せ．
  \item $\triangle$ABC の外接円は双曲線とさらに1点 D で交わり，D は H と原点に関して対称であることを示せ．
  \item $a=1$，$b=2$，$c=3$ のとき，H，D と外接円の中心を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 原点を中心とする半径1の円の外側の点 P$(a,b)$ から円に2本の接線を引くとき，2接点を通る直線 $l_{\mathrm P}$ の方程式を求めよ．
  \item 点 P$(a,b)$ が放物線 $y=\dfrac{x^2}4+2$ 上を動くとき，(1) のどの $l_{\mathrm P}$ も通らない点 $(x,y)$ の範囲を求めよ．
\end{enumerate}

放物線 $y=x^2$ 上の3点 P，Q，R が1辺の長さ $a$ の正三角形をなし，直線 PQ の傾きが $m$ であるとする．
\begin{enumerate}
  \item $3m^2\neq1$ のとき，$a$ を $m$ で表せ．また，$3m^2=1$ のときにはそのような正三角形が存在しないことを示せ．
  \item $m=1$ のとき，P，Q，R の座標を求めよ．
  \item $m$ を動かすとき，$a$ の最小値と，それを与える $m$ の値をすべて求めよ．
\end{enumerate}

円 $C:x^2+y^2=4$ の外部にある点 $\mathrm P(a,b)$ から $C$ に引いた2本の接線の接点を $\mathrm Q_1$，$\mathrm Q_2$ とし，線分 $\mathrm Q_1\mathrm Q_2$ の中点を Q とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{OQ}}=\dfrac4{a^2+b^2}\overrightarrow{\mathrm{OP}}$ を示せ．
  \item P が $C$ の外部で $b(a+b-4)<0$ をみたす範囲を動くとき，Q の存在範囲を図示せよ．
  \item (2) の範囲のうち $y<0$ の部分の面積を求めよ．
\end{enumerate}

放物線 $y=x^2$ 上に，直線 $y=a\left(x-\dfrac34\right)$ に関して対称な位置にある異なる2点 P，Q が存在するとする．
\begin{enumerate}
  \item $a$ の値の範囲を求めよ．
  \item $a$ が (1) の範囲を動くとき，線分 PQ の中点 M の軌跡を求めよ．
\end{enumerate}

$c>1$ とし，放物線 $A:y=x^2$ を直線 $l:y=2x-c$ に関して対称移動した曲線を $B$ とする．点 P が $A$ 上，点 Q が $B$ 上を動く．
\begin{enumerate}
  \item 線分 PQ の長さの最小値を $c$ で表せ．
  \item $c=2$ のとき，最小値を与える P，Q の座標を求めよ．
\end{enumerate}

曲線 $C$ を，原点を中心とする半径2の円のうち偏角が $0$ 以上 $\frac{2\pi}3$ 以下の弧とする．点 P，Q は $C$ 上にあり，線分 PQ の中点を R とする（P と Q が一致するときは R$=$P とする）．
\begin{enumerate}
  \item P が弧の中点 $\left(1,\sqrt3\right)$ に固定され，Q が $C$ 上を動くとき，R の軌跡を求めよ．
  \item P，Q が $C$ 上を自由に動くとき，R の動く範囲を図示し，その面積を求めよ．
\end{enumerate}

連立不等式 $y\geqq-1$，$y-2x\leqq-5$，$3y+4x\leqq25$ の表す領域を $A$，不等式 $x^2+y^2\leqq2$ の表す領域を $B$ とする．
\begin{enumerate}
  \item 点 $(x,y)$ が $A$ を動くとき，$\dfrac{y+1}{x-1}$ の最大値と最小値を求めよ．
  \item $k$ を実数とし，点 $(x,y)$ が $A$ を動くときの $y-kx$ の最小値と，$B$ を動くときの $y-kx$ の最大値が同じ値 $m$ であるとする．$k$ と $m$ の値を求めよ．
\end{enumerate}

実数 $x,y$ が $x^2+xy+y^2\leqq3$ をみたしながら変化する．
\begin{enumerate}
  \item $s=x+y$，$t=xy$ とするとき，点 $(s,t)$ の動く範囲を $st$ 平面上に図示し，その面積を求めよ．
  \item 負でない定数 $m$ に対して，$xy+m(x+y)$ の最大値と最小値を $m$ で表せ．
\end{enumerate}

$a,b$ を正の実数とする．
\begin{enumerate}
  \item $0<a<1$ をみたすどのような $a$ に対しても，$|3x-1|\leqq a$ かつ $|3y-2|\leqq a$ が $|x-y|\leqq b$ かつ $|x+y|\leqq b$ であるための十分条件であるという．そのような $b$ の最小値を求めよ．
  \item $a>1$ とする．$|3x-1|\leqq a$ かつ $|3y-2|\leqq a$ が $|x-y|\leqq1$ かつ $|x+y|\leqq1$ であるための必要条件であるという．そのような $a$ の最小値を求めよ．
\end{enumerate}

座標がともに整数である点を格子点という．
\begin{enumerate}
  \item 格子点を頂点とする三角形の面積は $\frac12$ 以上であることを示せ．
  \item 格子点を頂点とする正六角形は平面上に存在しないことを示せ．ただし，格子点を頂点とする正三角形が存在しないことは用いてよい．
  \item 格子点を頂点とする凸五角形の面積は 2 以上であることを示せ．
\end{enumerate}

楕円 $\dfrac{x^2}4+y^2=1$ の第1象限の点における接線が $x$ 軸，$y$ 軸の正の部分と交わる点を P，Q とし，O を原点とする．$a,b$ は正の定数とする．
\begin{enumerate}
  \item $a\mathrm{OP}^2+b\mathrm{OQ}^2$ の最小値を $a,b$ で表せ．
  \item 線分 PQ の長さの最小値を求めよ．
  \item $\mathrm{OP}+\mathrm{OQ}$ の最小値を求めよ．
\end{enumerate}

直線 $l:x=-3$ に接し，定円 $C:x^2+y^2=4$ に外接する円 $S$ と，直線 $l$ に接し，円 $C$ が内接する円 $T$ を考える．
\begin{enumerate}
  \item $S$ の中心の軌跡と $T$ の中心の軌跡を求めよ．
  \item $C$ 上の点 $(2\cos\theta,2\sin\theta)$（$0<\theta<\pi$）を $S$ と $T$ がともに通るとき，$S$ の中心 P と $T$ の中心 Q を求めよ．
  \item (2) の PQ の最小値と，そのときの $\cos\theta$ を求めよ．
\end{enumerate}

$a,b$ は実数で $b>0$ とする．整数 $m,n$ に対して $F(m,n)=(m+na)^2+n^2b^2$ とおく．
\begin{enumerate}
  \item $(m,n)=(0,1),(1,1),(-1,1)$ のすべてで $F(m,n)\geqq1$ となるための $a,b$ の条件を求め，点 $(a,b)$ の範囲を図示せよ．
  \item $|a|\leqq\frac12$，$a^2+b^2\geqq1$ ならば，$(m,n)\neq(0,0)$ であるすべての整数の組に対して $F(m,n)\geqq1$ であることを示せ．
  \item (1) の条件だけでは (2) の結論が成り立たない例をあげよ．
\end{enumerate}

4直線 $l_1,l_2,l_3,l_4$ が凸四角形 $\mathrm A_1\mathrm A_2\mathrm A_3\mathrm A_4$ の辺 $\mathrm A_1\mathrm A_2$，$\mathrm A_2\mathrm A_3$，$\mathrm A_3\mathrm A_4$，$\mathrm A_4\mathrm A_1$ を含み，それぞれ $l_i(x,y)=0$（$l_i$ は $x,y$ の1次式）で表されるとする．
\begin{enumerate}
  \item 任意の実数 $\lambda$ に対して，曲線 $K_\lambda:\ l_1(x,y)\,l_3(x,y)+\lambda\, l_2(x,y)\,l_4(x,y)=0$ は4点 $\mathrm A_1,\mathrm A_2,\mathrm A_3,\mathrm A_4$ を通ることを示せ．
  \item $\mathrm A_1(5,0)$，$\mathrm A_2(3,4)$，$\mathrm A_3(-4,3)$，$\mathrm A_4(0,-5)$ のとき，$l_1,\dots,l_4$ を求め，$K_\lambda$ が円となる $\lambda$ が存在することを示して，その円を求めよ．
  \item (2) で $\mathrm A_4$ を $(0,-4)$ に替えると，$K_\lambda$ が円となる $\lambda$ は存在しないことを示せ．このことから4点 $(5,0)$，$(3,4)$，$(-4,3)$，$(0,-4)$ について何がいえるか．
\end{enumerate}

$a$ が $-1\leqq a\leqq2$ の範囲を動くとき，直線 $\ell_a:y=2ax-a^2$ が通過する範囲を $E$ とする．
\begin{enumerate}
  \item $E$ を求め，図示せよ．
  \item $E$ のうち $-1\leqq x\leqq2$ の部分の面積を求めよ．
\end{enumerate}

実数 $t$ の値によって定まる2点 $\mathrm P(t+1,\ t^2)$，$\mathrm Q(t-1,\ -t^2)$ がある．$t$ が $0\leqq t\leqq1$ を動くとき，線分 PQ が通過する範囲を $D$ とする．
\begin{enumerate}
  \item 直線 $x=k$ と $D$ の共通部分を，$k$ の値で場合分けして求めよ．
  \item $D$ の面積を求めよ．
\end{enumerate}

$xy$ 平面上で，円 $C:x^2+y^2=1$ の外部にある点 $\mathrm P(a,b)$ を考える．P から $C$ に引いた2本の接線の接点を Q$_1$，Q$_2$ とし，線分 Q$_1$Q$_2$ の中点を Q とする．
\begin{enumerate}
  \item Q の座標を $a,b$ で表せ．
  \item P が $C$ の外部で $a+b>1$，$a^2+b^2<4$ をみたす範囲を動くとき，Q の存在する範囲を求め，図示せよ．
  \item (2) の条件から $a^2+b^2<4$ をはずしたとき，Q の存在する範囲の面積を求めよ．
\end{enumerate}

点 $(x,y)$ が $|x|<1$，$|y|<1$ の範囲を動くとき，$u=x+y$，$v=x^2+y^2$ で定まる点 $(u,v)$ の全体を $F$ とする．
\begin{enumerate}
  \item $F$ を求め，境界を含むか含まないかを明示して図示せよ．
  \item $F$ の面積を求めよ．
\end{enumerate}

連立方程式 $x+y=a$，$x^3+y^3=b$ の実数解 $x,y$ がともに $0\leqq x\leqq1$，$0\leqq y\leqq1$ をみたすような点 $(a,b)$ の範囲を $K$ とする．
\begin{enumerate}
  \item $K$ を求め，図示せよ．
  \item $K$ の面積を求めよ．
\end{enumerate}

放物線 $C:y=x^2$ 上に，$x$ 座標がそれぞれ $p,q$ である2点 $\mathrm{P},\mathrm{Q}$ をとる．ただし $-1\leqq p\leqq1$，$-1\leqq q\leqq1$ とする．線分 $\mathrm{PQ}$ を $1:3$ に内分する点（$\mathrm{P}$ に近い方）を $\mathrm{R}$ とする．
\begin{enumerate}
  \item $\mathrm{R}$ の座標を $(a,b)$ とする．$a$ を固定したとき，$b$ のとりうる値の範囲を求めよ．
  \item $p,q$ が動くとき，$\mathrm{R}$ が動く領域の面積を求めよ．
\end{enumerate}

座標平面の点 $(x,y)$ を点 $(y,\,-3x+4y)$ へ移す移動 $f$ を考える．直線 $l_0$ を $x+y=1$ とし，点Pが $l_n$ 上を動くとき $f(\mathrm P)$ が描く直線を $l_{n+1}$ とする $(n=0,1,2,\dots)$．$l_n$ を $a_nx+b_ny=1$ と表す．
\begin{enumerate}
  \item $a_{n+1},b_{n+1}$ を $a_n,b_n$ で表し，$a_n,b_n$ を $n$ の式で表せ．
  \item 不等式 $a_nx+b_ny>1$ の表す領域を $D_n$ とする．$D_0,D_1,D_2,\dots$ のすべてに含まれる点 $(x,y)$ の範囲を求めよ．
\end{enumerate}

$a>0$，$c>0$ とし，$\mathrm{A}(a,0)$，$\mathrm{B}(-a,0)$，$\mathrm{C}(b,c)$ とする．
\begin{enumerate}
  \item 三角形 ABC の外接円の中心と半径を $a,b,c$ で表せ．
  \item 外心が三角形 ABC の内部（周を除く）にあるための $a,b,c$ の条件を求めよ．
  \item $a=1$ とし，点 C が放物線 $y=x^2+2$ 上を動くとき，外接円の半径の最小値と，そのときの点 C の座標を求めよ．そのとき外心は三角形の内部にあるか．
\end{enumerate}

$\triangle\mathrm{ABC}$ の3辺の長さを $a,b,c$，$s=\dfrac{a+b+c}2$，外接円の半径を $R$，内接円の半径を $r$ とする．
\begin{enumerate}
  \item $\dfrac rR=\dfrac{4(s-a)(s-b)(s-c)}{abc}$ を示せ．
  \item $R\geqq2r$ を示し，等号が成り立つ条件を求めよ．
  \item 3辺の長さが $n-1,\ n,\ n+1$（$n$ は3以上の整数）である三角形について $\dfrac rR$ を $n$ で表せ．また，$\dfrac rR>0.49$ となる最小の $n$ を求めよ．
\end{enumerate}

$b>1$ とし，座標平面上に2点 $\mathrm{A}(0,1)$，$\mathrm{B}(0,b)$ をとる．$x>0$ に対し点 $\mathrm{P}(x,x)$ を考え，$\theta=\angle\mathrm{APB}$ とおく．
\begin{enumerate}
  \item $b=4$ のとき，$\theta$ を最大にする $x$ の値と，そのときの $\tan\theta$ の値を求めよ．
  \item $x$ を変化させたときの $\theta$ の最大値が $90^\circ$ 以上となるような $b$ の値の範囲を求めよ．
\end{enumerate}

$xy$ 平面において，原点 O とは異なる点 P に対し，Q を半直線 OP 上にあって $\mathrm{OP}\times\mathrm{OQ}=1$ をみたす点とする．
\begin{enumerate}
  \item P が直線 $x+y=2$ 上を動くとき，Q の軌跡を求めよ．
  \item P が円 $(x-2)^2+(y-1)^2=1$ 上を動くとき，Q の軌跡を求めよ．
  \item P が (2) の円のうち $y\geqq1$ の部分を動くとき，Q の軌跡を求めよ．
\end{enumerate}

座標平面上で，円 $K$ が放物線 $y=x^2$ に右下側（$y<x^2$ の側）から点 $\mathrm A(a,a^2)$（$a>0$）で接し，かつ $x$ 軸に上から接している．ただし，円と放物線がある点で接するとは，その点で両者が共有点をもち，かつその点における両者の接線が一致することをいう．
\begin{enumerate}
  \item $K$ の中心 C の座標と半径 $r$ を $a$ で表せ．
  \item $K$ と放物線 $y=x^2$ は A 以外に共有点をもたないことを示せ．
  \item $K$ と $x$ 軸の接点が $(2\sqrt2,\,0)$ であるとき，$a$ の値と $K$ の方程式を求めよ．
\end{enumerate}

$xy$ 平面の放物線 $y=x^2$ 上の3点 P，Q，R を頂点とする正三角形を考え，その一辺の長さを $a$ とする．
\begin{enumerate}
  \item 直線 PQ の傾きが $1$ であるとき，$a$ の値を求めよ．
  \item このような正三角形全体を考えるとき，$a$ の最小値を求めよ．また，最小となる正三角形の頂点の例を1つ挙げよ．
\end{enumerate}

2点 $\mathrm{A}(-2,\ 3)$，$\mathrm{B}(4,\ -1)$ について，次の点の座標を求めよ．
\begin{enumerate}
  \item 線分 $\mathrm{AB}$ を $1:2$ に内分する点
  \item 線分 $\mathrm{AB}$ を $3:1$ に外分する点
\end{enumerate}

3点 $\mathrm{A}(1,\ 2)$，$\mathrm{B}(5,\ -1)$，$\mathrm{C}(3,\ 5)$ について，次の問いに答えよ．
\begin{enumerate}
  \item $\triangle\mathrm{ABC}$ の重心 $\mathrm{G}$ の座標を求めよ．
  \item 四角形 $\mathrm{ABCD}$ が平行四辺形となるような点 $\mathrm{D}$ の座標を求めよ．
\end{enumerate}

2点 $\mathrm{A}(1,\ 3)$，$\mathrm{B}(5,\ 1)$ について，次の問いに答えよ．
\begin{enumerate}
  \item 線分 $\mathrm{AB}$ の長さを求めよ．
  \item $x$ 軸上の点 $\mathrm{P}$ で，$\mathrm{PA}=\mathrm{PB}$ となるものの座標を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 2点 $(-1,\ 4)$，$(3,\ -4)$ を通る直線の方程式を求めよ．
  \item 点 $(2,\ -3)$ を通り，傾きが $\dfrac12$ の直線の方程式を求めよ．
\end{enumerate}

点 $(2,\ 1)$ を通り，直線 $2x-3y+1=0$ に
\begin{enumerate}
  \item 平行な直線の方程式を求めよ．
  \item 垂直な直線の方程式を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 点 $(3,\ -2)$ と直線 $4x+3y-1=0$ の距離を求めよ．
  \item 平行な2直線 $x+2y-3=0$，$x+2y+7=0$ の距離を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 円 $x^2+y^2-4x+6y-3=0$ の中心の座標と半径を求めよ．
  \item 中心が $(-1,\ 2)$ で $x$ 軸に接する円の方程式を $x^2+y^2+lx+my+n=0$ の形で表すとき，定数 $l,\ m,\ n$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 円 $x^2+y^2=25$ 上の点 $(3,\ -4)$ における接線の方程式を求めよ．
  \item 円 $(x-1)^2+(y-2)^2=10$ 上の点 $(2,\ 5)$ における接線の方程式を求めよ．
\end{enumerate}

2つの円 $x^2+y^2=4$，$(x-3)^2+(y-4)^2=r^2$（$r>0$）について，次の場合の $r$ の値を求めよ．
\begin{enumerate}
  \item 2つの円が外接する．
  \item 2つの円が内接する．
\end{enumerate}

連立不等式 $x\geqq0,\ y\geqq0,\ x+2y\leqq6,\ 2x+y\leqq6$ の表す領域を $D$ とする．
\begin{enumerate}
  \item $D$ の面積を求めよ．
  \item 点 $(x,\ y)$ が $D$ 内を動くとき，$x+y$ の最大値を求めよ．
\end{enumerate}

2直線 $2x+y-4=0$，$x-y+1=0$ の交点を通る直線のうち，次の条件を満たすものの方程式を求めよ．
\begin{enumerate}
  \item 点 $(4,\ 0)$ を通る．
  \item 直線 $x+3y=0$ に垂直である．
\end{enumerate}

3点 $\mathrm{A}(-1,\ 2)$，$\mathrm{B}(3,\ -1)$，$\mathrm{C}(4,\ 5)$ について，次の問いに答えよ．
\begin{enumerate}
  \item 直線 $\mathrm{AB}$ の方程式を求めよ．
  \item 点 $\mathrm{C}$ と直線 $\mathrm{AB}$ の距離を求めよ．
  \item $\triangle\mathrm{ABC}$ の面積を求めよ．
\end{enumerate}

$k$ を定数とする直線 $\ell:\ (1+2k)x+(1-k)y-3=0$ について，次の問いに答えよ．
\begin{enumerate}
  \item $\ell$ は $k$ の値に関係なく定点を通る．その定点の座標を求めよ．
  \item $\ell$ が2点 $\mathrm{A}(4,\ 0)$，$\mathrm{B}(0,\ -2)$ を結ぶ線分と共有点をもつような $k$ の値の範囲を求めよ．
\end{enumerate}

点 $\mathrm{A}(3,\ 1)$ から円 $x^2+y^2=5$ に2本の接線を引く．
\begin{enumerate}
  \item 2本の接線の方程式を求めよ．
  \item 2つの接点を通る直線の方程式を求めよ．
\end{enumerate}

円 $C:\ x^2+y^2-4x-2y-4=0$ と直線 $\ell:\ x-y+1=0$ について，次の問いに答えよ．
\begin{enumerate}
  \item $C$ が $\ell$ から切り取る弦の長さを求めよ．
  \item その弦の中点の座標を求めよ．
\end{enumerate}

2つの円 $x^2+y^2=10$，$x^2+y^2-2x-4y=0$ は2点で交わる．
\begin{enumerate}
  \item 2つの交点を通る直線の方程式を求めよ．
  \item 2つの交点を結ぶ線分の長さを求めよ．
  \item 2つの交点と点 $(2,\ -1)$ を通る円の中心の座標と半径を求めよ．
\end{enumerate}

$x,\ y$ が4つの不等式 $x\geqq0,\ y\geqq0,\ x+2y\leqq8,\ 3x+y\leqq9$ を満たすとき，次の式の最大値と，そのときの $x,\ y$ の値を求めよ．
\begin{enumerate}
  \item $2x+3y$
  \item $x+3y$
\end{enumerate}

点 $(x,\ y)$ が円 $(x-2)^2+y^2=1$ 上を動くとき，次の問いに答えよ．
\begin{enumerate}
  \item $\dfrac{y}{x}$ の最大値と最小値を求めよ．
  \item $x^2+y^2$ の最大値と最小値を求めよ．
\end{enumerate}

$m$ が実数全体を動くとき，2直線 $mx-y=0$，$x+my-2=0$ の交点 $\mathrm{P}$ の軌跡を求めたい．
\begin{enumerate}
  \item 交点 $\mathrm{P}$ の座標を $m$ で表せ．
  \item $\mathrm{P}$ の軌跡は円から1点を除いたものである．円の中心の座標，半径，除かれる点の座標を求めよ．
\end{enumerate}

点 $(1,\ 2)$ を通り，$x$ 軸と $y$ 軸の両方に接する円は2つある．
\begin{enumerate}
  \item 2つの円の半径をそれぞれ求めよ．
  \item 2つの円の中心間の距離を求めよ．
\end{enumerate}

円 $C_1:\ x^2+y^2-6x-8y+16=0$ と円 $C_2:\ x^2+y^2=r^2$（$r>0$）について，次の問いに答えよ．
\begin{enumerate}
  \item $C_1$ の中心の座標と半径を求めよ．
  \item $C_1$ と $C_2$ が共有点をもつような $r$ の値の範囲を求めよ．
\end{enumerate}

連立不等式 $x^2+y^2\leqq4,\ x+y\geqq2$ の表す領域を $D$ とする．
\begin{enumerate}
  \item $D$ の面積を求めよ．
  \item 点 $(x,\ y)$ が $D$ 内を動くとき，$x+2y$ の最大値と最小値を求めよ．
\end{enumerate}

3点 $\mathrm{A}(0,\ 3)$，$\mathrm{B}(-1,\ 0)$，$\mathrm{C}(3,\ 0)$ を頂点とする $\triangle\mathrm{ABC}$ について，次の問いに答えよ．
\begin{enumerate}
  \item $\triangle\mathrm{ABC}$ の垂心 $\mathrm{H}$ の座標を求めよ．
  \item $\triangle\mathrm{ABC}$ の外心 $\mathrm{O}^\prime$ の座標と外接円の半径を求めよ．
\end{enumerate}

座標平面の点 $(x,y)$ を $(x-y,\ x+y)$ へ移す移動 $f$ を考え，点 P が移る先を $f(\mathrm P)$ と表す．$f$ を用いて直線 $l_0,l_1,l_2,\dots$ を次のように定める．
\begin{itemize}
  \item $l_0$ は直線 $x=1$ である．
  \item 点 P が $l_n$ 上を動くとき，$f(\mathrm P)$ が描く直線を $l_{n+1}$ とする $(n=0,1,2,\dots)$．
\end{itemize}
$l_n$ を1次式を用いて $a_nx+b_ny=1$ と表す．
\begin{enumerate}
  \item $a_{n+1},\ b_{n+1}$ を $a_n,\ b_n$ で表せ．また $a_{n+8}=\dfrac{a_n}{16},\ b_{n+8}=\dfrac{b_n}{16}$ を示せ．
  \item 不等式 $a_nx+b_ny\leqq1$ が定める領域を $E_n$ とする．$E_0,E_1,E_2,\dots$ すべてに含まれる点の範囲を図示し，その面積を求めよ．
\end{enumerate}

放物線 $y=x^2$ 上の相異なる3点 P$(p,p^2)$，Q$(\alpha,\alpha^2)$，R$(\beta,\beta^2)$ が $\angle\mathrm{QPR}=90^\circ$ をみたしながら動くとき，$\triangle$PQR の重心を G$(X,Y)$ とする．
\begin{enumerate}
  \item $p=\dfrac12$ に固定するとき，G の軌跡を求めよ．
  \item P も放物線上を自由に動くとき，G の存在範囲を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $a$ を正の実数とする．直線 $l$ に関する対称移動によって，点 A$(0,1)$ が直線 $y=-1$ 上の点に，点 B$(a,0)$ が直線 $x=-a$ 上の点に移るという．このような直線 $l$ はただ1つ存在することを示し，その傾きを $a$ を用いて表せ．
  \item $b$ を実数とする．直線 $l$ に関する対称移動によって，点 A$(0,1)$ が直線 $y=-1$ 上の点に，点 B$(1,b)$ が直線 $x=-1$ 上の点に移るような直線 $l$ の本数を，$b$ の値によって分類して答えよ．
\end{enumerate}

$xy$ 平面上の2点 P，Q に対し，P と Q を $x$ 軸または $y$ 軸に平行な線分からなる折れ線で結ぶときの経路の長さの最小値を $d(\mathrm P,\mathrm Q)$ で表す．O$(0,0)$，A$(4,0)$ とする．
\begin{enumerate}
  \item B$(1,3)$ のとき，$d(\mathrm O,\mathrm P)=d(\mathrm A,\mathrm P)=d(\mathrm B,\mathrm P)$ をみたす点 P をすべて求めよ．
  \item 点 B$(u,v)$ は O，A のいずれとも異なるとする．$d(\mathrm O,\mathrm P)=d(\mathrm A,\mathrm P)=d(\mathrm B,\mathrm P)$ をみたす点 P が無数に存在するような点 B の範囲を求めよ．
  \item (2) と同じ B について，そのような点 P が1つも存在しないような点 B の範囲を求めよ．
\end{enumerate}

座標平面上に放物線 $C:\ y=x^2-3x+4$ と領域 $D:\ y\geqq x^2-3x+4$ を定める．原点を通り $C$ に接する2直線のうち，傾きの大きい方を $l$，小さい方を $m$ とする．
\begin{enumerate}
  \item $C$ 上の点 A と直線 $l$，$m$ の距離をそれぞれ $L$，$M$ とする．正の定数 $k$ に対し，A が $C$ 上を動くときの $\sqrt L+k\sqrt M$ の最小値を考える．最小値をとる点 A が無数に存在するような $k$ の値を求めよ．また，そのときの最小値と，最小値をとる点 A の $x$ 座標の範囲を求めよ．
  \item 次の条件をみたす点 $(p,q)$ の動きうる範囲を求め，図示せよ．
  \begin{center}
  条件：領域 $D$ のすべての点 $(x,y)$ に対して $px+qy\leqq1$ が成り立つ．
  \end{center}
\end{enumerate}

O を原点とする座標平面において，点 A$(2,2)$ を通り，線分 OA と垂直な直線を $l$ とする．座標平面上を点 P$(p,q)$ が次の2つの条件をみたしながら動く．
\begin{itemize}
  \item[条件1：] $4\leqq\overrightarrow{\mathrm{OA}}\cdot\overrightarrow{\mathrm{OP}}\leqq17$
  \item[条件2：] 点 O と直線 $l$ の距離を $c$，点 P と直線 $l$ の距離を $d$ とするとき $cd\geqq(p-1)^2$
\end{itemize}
P が動く領域を $D$ とする．さらに，$x$ 軸の正の部分と線分 OP のなす角を $\theta$（$0\leqq\theta\leqq\pi$）とする．
\begin{enumerate}
  \item $D$ を図示し，その面積を求めよ．
  \item $\cos\theta$ のとりうる値の範囲を求めよ．
\end{enumerate}

$a$ を実数とし，座標平面上の点 $(0,a)$ を中心とする半径1の円を $C$ とする．$t\geqq0$ に対し，放物線 $y=x^2$ 上の点 $(t,t^2)$ における接線を $\ell_t$ とする．$\ell_t$ が $C$ と異なる2点で交わるとき，その2交点を結ぶ線分の長さを $L(t)$ とする．
\begin{enumerate}
  \item $\ell_t$ が $C$ と異なる2点で交わるような $t\geqq0$ が存在する $a$ の範囲を求めよ．
  \item $\ell_{t_1}$，$\ell_{t_2}$ がともに $C$ と異なる2点で交わり，$L(t_1)=L(t_2)$ となるような相異なる $t_1\geqq0$，$t_2\geqq0$ が存在する $a$ の範囲を求めよ．
\end{enumerate}

$a,b$ を実数とし，座標平面上の放物線 $y=x^2+ax+b$ を $C$ とする．$C$ は原点で垂直に交わる2本の接線 $\ell_1$，$\ell_2$ をもつとする．ただし，$C$ と $\ell_1$ の接点 $\mathrm P_1$ の $x$ 座標は，$C$ と $\ell_2$ の接点 $\mathrm P_2$ の $x$ 座標より小さいとする．$i=1,2$ に対し，円 $D_i$ を，$C$ の軸上に中心をもち，点 $\mathrm P_i$ で $\ell_i$ に接するものと定める．
\begin{enumerate}
  \item $b$ を $a$ で表せ．
  \item $D_1$ と $D_2$ が共有点をもつような $a$ の値の範囲を求めよ．
  \item $D_1$ と $D_2$ が異なる2点で交わるとき，その2点を結ぶ線分の長さの最大値と，最大値を与える $a$ の値を求めよ．
\end{enumerate}

座標平面上で，放物線 $C:y=ax^2+bx+c\ (a<0)$ が円 $x^2+y^2=1$ と異なる2点 P，Q を共有し，P と Q のそれぞれにおいて円と共通の接線をもつとする．
\begin{enumerate}
  \item $b=0$ であることを示せ．さらに，P の $y$ 座標を $s$ とするとき，$a,\ c$ を $s$ で表し，$s$ のとりうる値の範囲を求めよ．
  \item 条件をみたす放物線 $C$ 全体が通過する領域を $D$ とする．$D$ を図示せよ．
  \item $D$ のうち $0\leqq y\leqq1$ をみたす部分の面積を求めよ．
\end{enumerate}

座標平面上に2点 O$(0,0)$，A$(0,1)$ をとる．$x$ 軸上の2点 P$(p,0)$，Q$(q,0)$ が，次の条件 (i)，(ii) をともにみたすとする．
\begin{center}
(i)\ $0<p<1$ かつ $p<q$\qquad (ii)\ 線分 AP の中点を M とするとき，$\angle\mathrm{OAP}=\angle\mathrm{PMQ}$
\end{center}
さらに，直線 MQ と $y$ 軸の交点を R とする．
\begin{enumerate}
  \item $q$ を $p$ で表せ．
  \item R の座標を $p$ で表せ．また，直線 AP は3点 O，M，R を通る円に点 M で接することを示せ．
  \item (2) の円の半径の最小値と，そのときの $p$ の値を求めよ．
\end{enumerate}

$f(x)=-\dfrac{\sqrt2}{4}x^2+4\sqrt2$ とおく．$0<t<4$ をみたす実数 $t$ に対し，座標平面上の点 $(t,f(t))$ を通り，この点において放物線 $y=f(x)$ と共通の接線をもち，$x$ 軸上に中心をもつ円を $C_t$ とする．
\begin{enumerate}
  \item $C_t$ と放物線 $y=f(x)$ の共有点の $x$ 座標をすべて $t$ で表せ．
  \item $C_t$ と放物線 $y=f(x)$ の共有点の個数を，$t$ の値によって分類して答えよ．
  \item $2<t<2\sqrt3$ のとき，$C_t$ と放物線 $y=f(x)$ の3個の共有点を頂点とする三角形の面積の最大値と，そのときの $t$ の値を求めよ．
\end{enumerate}

$\triangle$ABC は鋭角三角形で，$\angle A=\dfrac{\pi}{3}$，外接円の半径は1であるとする．$\triangle$ABC の外心を O，垂心を H，内心を I とする．
\begin{enumerate}
  \item 5点 B，C，O，H，I は同一円周上にあることを示し，その円の半径を求めよ．
  \item OI$=$IH であることを示せ．
  \item 3点 O，H，I が三角形の3頂点となるとき，$\triangle$OHI の面積 $S$ のとりうる値の範囲を求めよ．
\end{enumerate}

次の命題 (p)，(q) のそれぞれについて，正しいかどうか答えよ．正しければ証明し，正しくなければ反例を挙げよ．
\begin{enumerate}
  \item[(p)] 正 $n$ 角形の頂点から3点を選んで，内角の1つが $45^\circ$ である直角三角形でない三角形を作ることができるならば，$n$ は8の倍数である．
  \item[(q)] 平面上に $\triangle$ABC と $\triangle$ABD があり，C，D は直線 AB に関して同じ側にあって，$\angle$CAB と $\angle$CBA はともに鋭角であるとする．このとき，AC$<$AD かつ BC$<$BD ならば $\angle$ACB$>\angle$ADB である．
\end{enumerate}

$t$ を正の実数とし，座標平面上に2点 A$(0,t)$，B$(0,t+1)$ をとる．正の実数 $x$ に対して点 P$(x,x)$ をとる．
\begin{enumerate}
  \item $x$ が正の実数全体を動くとき，$\angle$APB の最大値 $\theta(t)$ が存在することを示せ．また，$\theta(t)\geqq\dfrac{\pi}{2}$ となる $t$ の範囲を求めよ．
  \item $t$ が正の実数全体を動くとき，$\theta(t)$ のとりうる値の範囲を求めよ．
\end{enumerate}

鋭角三角形 ABC の内部（辺や頂点は含まない）に点 P をとり，$\triangle$PBC，$\triangle$PCA，$\triangle$PAB の外心をそれぞれ A$'$，B$'$，C$'$ とする．
\begin{enumerate}
  \item A$'$，B$'$，C$'$ は三角形の3頂点となり，直線 B$'$C$'$ は直線 PA に垂直であることを示せ．
  \item $\triangle$A$'$B$'$C$'$ と $\triangle$ABC が，A$'$，B$'$，C$'$ がそれぞれ A，B，C に対応して相似となるための必要十分条件は，P が $\triangle$ABC の垂心であることを示せ．
  \item P が $\triangle$ABC の垂心であるとき，$\triangle$A$'$B$'$C$'$ と $\triangle$ABC は合同であることを示せ．
\end{enumerate}

AB$=$AC$=1$，$\angle$BAC$=\theta$（$0<\theta<\pi$）の二等辺三角形 ABC がある．辺 AB 上に A，B と異なる点 M をとり，辺 AB を B の側に延長した半直線上（B を除く）に点 N を $\angle$BCM$=\angle$BCN となるようにとる．
\begin{enumerate}
  \item このような点 N はただ1つ存在し，AM$\cdot$AN$=1$ であることを示せ．
  \item $\triangle$CMN の外接円は直線 AC に点 C で接することを示せ．
  \item M が辺 AB 上（A，B を除く）を動くとき，$\triangle$CMN の外接円の中心の軌跡を求めよ．
\end{enumerate}

座標平面上の単位円 $C:x^2+y^2=1$ 上に点 P をとり，定点 A$(-2,0)$ から P へ線分を引く．$k$ を正の定数とし，線分 AP の P の側の延長上に点 Q を AP$\cdot$PQ$=k$ となるようにとる．$s=\mathrm{AP}$，$t=\mathrm{OQ}$（O は原点）とおく．
\begin{enumerate}
  \item $t^2$ を $s$ と $k$ で表せ．
  \item P が $C$ 上を動くとき，Q がつねに1つの円周上にあるような $k$ の値を求め，そのときの Q の軌跡を求めよ．
  \item $k=1$ のとき，$t$ のとりうる値の範囲を求めよ．
\end{enumerate}

放物線 $y=x^2$ と円 $K$ が異なる4点で交わっている．この4点を $K$ 上で順に A，B，C，D とすると，対角線 AC と BD が直交しているとする．
\begin{enumerate}
  \item 直線 AC，BD の傾きを求めよ．
  \item 対角線 AC，BD の交点 P の存在範囲を求めよ．
  \item 円 $K$ の中心の存在範囲を求めよ．
\end{enumerate}

$xy$ 平面上で $y=x^2+a$ と $y=\dfrac1x$ が異なる3つの交点をもつとき，3交点を $x$ 座標の小さい方から順に A，B，C とする．
\begin{enumerate}
  \item 異なる3交点をもつような $a$ の範囲を求めよ．
  \item $\triangle\mathrm{ABC}$ が鋭角三角形，直角三角形，鈍角三角形となる $a$ の範囲をそれぞれ求め，直角・鈍角となる角がどれかも答えよ．
  \item $\triangle\mathrm{ABC}$ が直角三角形のとき，その面積を求めよ．
\end{enumerate}

$f(x)=x^3-x$ とし，$0<r\leqq1$ に対して，曲線 $y=f(x)$ の $1-r\leqq x\leqq1+r$ の部分を $C_r$ とする．また $p=1-r$，$q=1+r$ とし，$C_r$ の両端を $\mathrm P(p,f(p))$，$\mathrm Q(q,f(q))$ とする．
\begin{enumerate}
  \item すべての実数 $x$ に対して，次の等式が成り立つことを示せ．
  \begin{align*}
  &(x-p)(x-q)+\{f(x)-f(p)\}\{f(x)-f(q)\}\\
  &\qquad=(x-p)(x-q)\left\{1+(x^2+px+p^2-1)(x^2+qx+q^2-1)\right\}
  \end{align*}
  \item $0<r\leqq\dfrac25$ のとき，$C_r$ を内部または周上に含む円の半径の最小値 $R(r)$ を $r$ で表せ．
  \item $r=1$ のとき，線分 PQ を直径とする円の内部および周上に $C_1$ は含まれないことを示せ．
\end{enumerate}

$r>0$，$k$ を実数の定数とし，円 $C:x^2+y^2=r^2$ と放物線 $D:y=x^2-k$ を考える．
\begin{enumerate}
  \item $b\neq c$ のとき，$D$ 上の2点 $(b,b^2-k)$，$(c,c^2-k)$ を通る直線が $C$ に接するための必要十分条件は $(bc+k)^2=r^2\{(b+c)^2+1\}$ であることを示せ．
  \item $D$ 上の点 $\mathrm P(a,a^2-k)$ が $C$ の外部にあり，$a^2\neq r^2$ であるとき，P を「よい点」とよぶ．よい点 P から $C$ に引いた2本の接線は，それぞれ $D$ と P 以外の点でただ1回交わるか，P で $D$ に接する．前者の場合はその交点を，後者の場合は P 自身を考え，2本の接線について得られる $D$ 上の点を Q，R とする．このとき Q $\neq$ R であることを示せ．さらに，すべてのよい点 P について直線 QR が $C$ に接するような $k$ を，$r$ を用いてすべて求めよ．
  \item $r=1$，$k=2$，$\mathrm P(2,2)$ のとき，直線 QR の方程式を求めよ．
\end{enumerate}
